CREATE TABLE public.health_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, record_type text NOT NULL DEFAULT 'Medical record', record_date text, file_path text, mime_type text, analysis jsonb, fhir_resource jsonb, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.health_records TO authenticated; GRANT ALL ON public.health_records TO service_role; ALTER TABLE public.health_records ENABLE ROW LEVEL SECURITY; CREATE POLICY own_records ON public.health_records FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE INDEX health_records_owner ON public.health_records(user_id, created_at DESC); CREATE TABLE public.health_preferences (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT '', abha_id text, language text NOT NULL DEFAULT 'English'); GRANT SELECT, INSERT, UPDATE ON public.health_preferences TO authenticated; GRANT ALL ON public.health_preferences TO service_role; ALTER TABLE public.health_preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY own_preferences ON public.health_preferences FOR ALL TO authenticated USING(auth.uid() = user_id) WITH CHECK(auth.uid() = user_id); CREATE TABLE public.ai_access_state (user_id uuid PRIMARY KEY, message text NOT NULL, status integer NOT NULL, blocked boolean NOT NULL DEFAULT true); GRANT SELECT ON public.ai_access_state TO authenticated; GRANT ALL ON public.ai_access_state TO service_role; ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY; CREATE POLICY own_ai_state ON public.ai_access_state FOR SELECT TO authenticated USING(auth.uid() = user_id); CREATE POLICY health_files ON storage.objects FOR ALL TO authenticated USING(bucket_id = 'health-records' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK(bucket_id = 'health-records' AND (storage.foldername(name))[1] = auth.uid()::text);